use xiom.io;

enum Genre {
  Action,
  Comedy,
  Drama,
  SciFi,
  Horror,
}

type Movie = {
  title: Str;
  genre: Genre;
  year: Int;
}

fn is_classic(m: Movie) -> Bool {
  return m.year < 2000;
}

fn is_action(m: Movie) -> Bool {
  return m.genre == Genre.Action;
}

fn main() -> Int {
  let m1 = Movie{ title: "Die Hard"; genre: Genre.Action; year: 1988; };
  let m2 = Movie{ title: "Fury Road"; genre: Genre.Action; year: 2015; };
  let m3 = Movie{ title: "Inception"; genre: Genre.Action; year: 2010; };
  var count = 0;
  if is_classic(m1) && is_action(m1) { count = count + 1; }
  if is_classic(m2) && is_action(m2) { count = count + 1; }
  if is_classic(m3) && is_action(m3) { count = count + 1; }
  return count;
}
